  left: 0;
  right: auto;
}

.katex-display.fleqn>.katex {
  text-align: left;
  padding-left: 2em;
}

body {
  counter-reset: katexEqnNo mmlEqnNo;
}

/**
 * Code-block styling for the MarkdownViewer card.
 *
 * Works in concert with `highlight.js/styles/github.css` (imported in the
 * component) to give code a GitHub-like appearance:
 *
 *  • Fenced code blocks  →  light-gray bg, rounded border, 13 px mono
 *  • Inline code         →  muted pill, slightly smaller than body text
 *
 * These rules are intentionally scoped to elements that react-markdown
 * produces so they do not bleed into the rest of the application.
 */

/* ── Fenced code blocks ────────────────────────────────────────────────────── */

/* Override highlight.js's own background so the block matches GitHub's
   #f6f8fa rather than pure white, and clamp the font to a readable size. */
code.hljs {
  background-color: #f6f8fa;
  font-size: 0.8125rem;
  /* 13 px */
  line-height: 1.65;
  padding: 0;
  /* padding lives on <pre> below */
  border-radius: 0;
  /* radius lives on <pre> below */
}

/* The <pre> wrapper: add GitHub-style border + padding + corner radius. */
pre:has(code.hljs) {
  background-color: #f6f8fa;
  border: 1px solid #d0d7de;
  border-radius: 0.5rem;
  /* 8 px */
  padding: 1rem;
  overflow-x: auto;
  margin: 0.25rem 0;
}

/* Dark-mode overrides — keep readable against the dark surface */
@media (prefers-color-scheme: dark) {
  code.hljs {
    background-color: #161b22;
    color: #c9d1d9;
  }

  pre:has(code.hljs) {
    background-color: #161b22;
    border-color: #30363d;
  }
}

/* ── Typography — headings, paragraphs, lists, etc. ────────────────────────── */

/* Headings: size, weight, and spacing matching GitHub's rendered markdown. */
.md-prose h1 {
  font-size: 2em;
  font-weight: 600;
  line-height: 1.25;
  padding-bottom: 0.3em;
  border-bottom: 1px solid #d0d7de;
  margin: 1.5rem 0 1rem;
}

.md-prose h2 {
  font-size: 1.5em;
  font-weight: 600;
  line-height: 1.25;
  padding-bottom: 0.3em;
  border-bottom: 1px solid #d0d7de;
  margin: 1.5rem 0 1rem;
}

.md-prose h3 {
  font-size: 1.25em;
  font-weight: 600;
  line-height: 1.25;
  margin: 1.25rem 0 0.75rem;
}

.md-prose h4 {
  font-size: 1em;
  font-weight: 600;
  line-height: 1.25;
  margin: 1rem 0 0.5rem;
}

.md-prose h5,
.md-prose h6 {
  font-size: 0.875em;
  font-weight: 600;
  line-height: 1.25;
  margin: 1rem 0 0.5rem;
}

/* Paragraphs */
.md-prose p {
  margin: 0 0 1rem;
  line-height: 1.75;
}

/* Unordered and ordered lists */
.md-prose ul,
.md-prose ol {
  padding-left: 2em;
  margin: 0 0 1rem;
  line-height: 1.75;
}

.md-prose ul {
  list-style-type: disc;
}

.md-prose ol {
  list-style-type: decimal;
}

.md-prose li {
  margin: 0.25em 0;
}

.md-prose li>p {
  margin: 0;
}

/* Nested lists */
.md-prose ul ul,
.md-prose ul ol,
.md-prose ol ul,
.md-prose ol ol {
  margin-bottom: 0;
}

/* Blockquotes */
.md-prose blockquote {
  border-left: 4px solid #d0d7de;
  padding: 0 1em;
  color: #656d76;
  margin: 0 0 1rem;
}

.md-prose blockquote>p {
  margin: 0;
}

/* Horizontal rules */
.md-prose hr {
  border: 0;
  border-top: 1px solid #d0d7de;
  margin: 1.5rem 0;
}

/* Links */
.md-prose a {
  color: #0969da;
  text-decoration: none;
}

.md-prose a:hover {
  text-decoration: underline;
}

/* Strong / emphasis */
.md-prose strong {
  font-weight: 600;
}

@media (prefers-color-scheme: dark) {

  .md-prose h1,
  .md-prose h2 {
    border-bottom-color: #30363d;
  }

  .md-prose hr {
    border-top-color: #30363d;
  }

  .md-prose blockquote {
    border-left-color: #30363d;
    color: #8b949e;
  }

  .md-prose a {
    color: #58a6ff;
  }
}

/* ── Tables (GitHub-like) ───────────────────────────────────────────────────── */

/* Scoped to .md-prose so these rules never bleed into app-level tables. */
.md-prose table {
  border-collapse: collapse;
  width: 100%;
  font-size: 0.875rem;
  margin: 0.75rem 0;
  overflow-x: auto;
  display: block;
}

.md-prose thead tr {
  background-color: #f6f8fa;
}

.md-prose th,
.md-prose td {
  border: 1px solid #d0d7de;
  padding: 6px 13px;
  text-align: left;
  white-space: normal;
}

.md-prose tbody tr:nth-child(even) {
  background-color: #f6f8fa;
}

@media (prefers-color-scheme: dark) {

  .md-prose thead tr,
  .md-prose tbody tr:nth-child(even) {
    background-color: #161b22;
  }

  .md-prose th,
  .md-prose td {
    border-color: #30363d;
  }
}

/* ── Inline code ────────────────────────────────────────────────────────────── */

/* Style inline `code` spans that are NOT inside a fenced block.
   Uses rgba so it stays subtle in both light and dark themes. */
:not(pre)>code {
  font-size: 0.875em;
  font-family: ui-monospace, "SFMono-Regular", "SF Mono", Menlo, Consolas,
    "Liberation Mono", monospace;
  background-color: rgba(175, 184, 193, 0.2);
  border-radius: 0.25rem;
  /* 4 px */
  padding: 0.15em 0.4em;
  white-space: nowrap;
}

import React, {useState} from "react";
import ReactMarkdown from "react-markdown";
import type {Components} from "react-markdown";
import {type PiCardProps} from "@pihanga2/core";
import remarkMath from "remark-math";
import remarkGfm from "remark-gfm";
import rehypeKatex from "rehype-katex";
import rehypeHighlight from "rehype-highlight";
import rehypeMermaid from "rehype-mermaid";
import "./katex.css";
import "highlight.js/styles/github.css";
import "./markdownViewer.code.css";

import type {MarkdownViewerProps} from "./markdownViewer.types";

/**
 * Default component overrides applied to every MarkdownViewer instance.
 *
 * Goals:
 *  - Fenced code blocks  → GitHub-like appearance (handled via CSS + rehype-highlight)
 *  - Inline `code` spans → subtle muted-pill style (handled via CSS)
 *
 * The `node` prop injected by react-markdown is destructured and discarded
 * here so it doesn't propagate to native DOM elements and trigger React
 * "unknown prop" warnings.
 */
const DEFAULT_COMPONENTS: Components = {
  // Pass `node` through as `_node` to keep it out of the DOM spread.
  pre: ({node: _node, children, ...rest}) => <pre {...rest}>{children}</pre>,
  code: ({node: _node, children, ...rest}) => <code {...rest}>{children}</code>,
};

export const MarkdownViewerComponent = (
  props: PiCardProps<MarkdownViewerProps>,
): React.ReactNode => {
  const {
    source,
    path,
    maxBodyLength = -1,
    remarkPlugins = [remarkMath, remarkGfm],
    rehypePlugins = [rehypeKatex, rehypeHighlight, rehypeMermaid],
    remarkRehypeOptions,
    components,
    className,
    style = {},
    cardName,
    _cls,
  } = props;

  const [fetchedText, setFetchedText] = useState("");
  const text = source || fetchedText;

  if (path && fetchedText === "") {
    fetch(path)
      .then((response) => response.text())
      .then((fetched) => setFetchedText(fetched));
  }

  function decode(s: string): string {
    try {
      return decodeURI(s);
    } catch {
      // may fail if actually not encoded and contains '%'
      return s;
    }
  }

  function shortenBody(body: string): string {
    if (body.length <= maxBodyLength) return body;

    const shortened = body
      .split(" ")
      .reduce(
        (p, el) => {
          const [a, cnt] = p;
          if (cnt < maxBodyLength) {
            return [a.concat(el), cnt + el.length + 1] as [string[], number];
          } else {
            return p;
          }
        },
        [[], 0] as [string[], number],
      )[0]
      .join(" ");
    return shortened.length < body.length ? `${shortened}...` : body;
  }

  const decoded = decode(text);
  const content = maxBodyLength > 0 ? shortenBody(decoded) : decoded;

  // Merge caller-supplied component overrides on top of our defaults.
  const mergedComponents: Components = {...DEFAULT_COMPONENTS, ...components};

  return (
    <div
      className={_cls("root", className)}
      style={style}
      data-pihanga={cardName}
    >
      <ReactMarkdown
        remarkPlugins={remarkPlugins}
        rehypePlugins={
          rehypePlugins as Parameters<typeof ReactMarkdown>[0]["rehypePlugins"]
        }
        remarkRehypeOptions={remarkRehypeOptions}
        components={mergedComponents}
        className={`${_cls("inner")} md-prose`}
      >
        {content}
      </ReactMarkdown>
    </div>
  );
};

import {createCardDeclaration} from "@pihanga2/core";
import type {PluggableList} from "unified";
import type {Components} from "react-markdown";

export const MARKDOWN_CARD = "markdown-viewer";

export const MarkdownViewer =
  createCardDeclaration<MarkdownViewerProps>(MARKDOWN_CARD);

export type MarkdownViewerProps<S = object> = {
  /** Markdown source string to render directly. */
  source?: string;
  /** URL/path to a file whose text content will be fetched and rendered. */
  path?: string;
  /**
   * Truncate rendered text to approximately this many characters (word boundary).
   * A negative value (default: -1) disables truncation.
   */
  maxBodyLength?: number;

  remarkPlugins?: PluggableList;
  rehypePlugins?: PluggableList;
  remarkRehypeOptions?: object;

  /**
   * Custom element renderers passed directly to `react-markdown`.
   * Merged on top of the card's built-in defaults (code/pre styling).
   * Use this to override how individual HTML elements are rendered.
   */
  components?: Components;

  /** Additional CSS class to apply to the outer wrapper div. */
  className?: string;
  style?: S;
};
